import type { HackonConfig } from '../config/schema.js'

export type AgentRole = 'coordinator' | 'implementer' | 'reviewer'

export function formatComment(role: AgentRole, body: string, config: HackonConfig): string {
  const prefix = config.github.commentPrefixes[role]
  return `${prefix} ${body}`
}

export function parseCommentRole(comment: string, config: HackonConfig): AgentRole | null {
  const prefixes = config.github.commentPrefixes
  if (comment.startsWith(prefixes.coordinator)) return 'coordinator'
  if (comment.startsWith(prefixes.implementer)) return 'implementer'
  if (comment.startsWith(prefixes.reviewer)) return 'reviewer'
  return null
}
